// helper to get username
fn get_username(repo: &Path) -> String {
    if let Ok(s) = run_git(repo, &["config", "user.name"]) {
        s
    } else { String::new() }
}

fn get_repo_name(repo: &Path) -> String {
    if let Ok(url) = run_git(repo, &["remote", "get-url", "origin"]) {
        let url = url.trim();
        if url.is_empty() { return String::new(); }
        // take basename, strip .git, handle trailing slash?
        let mut u = url.trim_end_matches('/').to_string();
        // handle scp-like git@github.com:alice/repo.git -> take after : or /
        if let Some(pos) = u.rfind(|c| c=='/' || c==':') {
            u = u[pos+1..].to_string();
        }
        if u.ends_with(".git") { u = u[..u.len()-4].to_string(); }
        // also handle file:// prefix? already handled via / and :
        // for local path like /tmp/brancheremote -> basename brancheremote
        u
    } else { String::new() }
}

fn get_branches(repo: &Path) -> usize {
    if let Ok(out) = run_git(repo, &["branch", "-r"]) {
        let mut count = 0;
        for line in out.lines() {
            let l = line.trim();
            if l.is_empty() { continue; }
            // exclude HEAD symbolic? e.g., origin/HEAD -> origin/main contains "->"
            if l.contains("->") { continue; }
            count += 1;
        }
        if count > 0 { count - 1 } else { 0 }
    } else { 0 }
}

fn get_tags(repo: &Path) -> usize {
    if let Ok(out) = run_git(repo, &["tag", "--list"]) {
        if out.is_empty() { 0 } else { out.lines().filter(|l| !l.trim().is_empty()).count() }
    } else { 0 }
}

fn get_tag_list(repo: &Path) -> Vec<String> {
    if let Ok(out) = run_git(repo, &["tag", "--list"]) {
        let mut v: Vec<String> = out.lines().map(|s| s.trim().to_string()).filter(|s| !s.is_empty()).collect();
        v.sort();
        v
    } else { vec![] }
}

fn parse_cargo_toml(repo: &Path) -> Option<(Option<String>, Option<String>, usize)> {
    // returns (description, version, dep_count)
    let p = repo.join("Cargo.toml");
    let content = std::fs::read_to_string(&p).ok()?;
    // naive parsing: look for [package] then description, version, and [dependencies] count?
    // For description: find line starting with description =
    // For version: find version = in [package] section?
    // For deps: count entries in [dependencies] section?
    let mut desc: Option<String> = None;
    let mut ver: Option<String> = None;
    let mut in_package = false;
    let mut in_deps = false;
    let mut dep_count = 0;
    for line in content.lines() {
        let t = line.trim();
        if t.starts_with('[') {
            in_package = t == "[package]";
            in_deps = t == "[dependencies]";
            continue;
        }
        if in_package {
            if t.starts_with("description") {
                if let Some(eq) = t.find('=') {
                    let v = t[eq+1..].trim().trim_matches('"').trim_matches('\'').to_string();
                    if !v.is_empty() { desc = Some(v); }
                }
            }
            if t.starts_with("version") {
                if let Some(eq) = t.find('=') {
                    let v = t[eq+1..].trim().trim_matches('"').trim_matches('\'').to_string();
                    // remove comments?
                    let v = v.split('#').next().unwrap_or(&v).trim().trim_matches('"').trim_matches('\'').to_string();
                    if !v.is_empty() { ver = Some(v); }
                }
            }
        }
        if in_deps {
            if t.is_empty() || t.starts_with('#') || t.starts_with('[') { continue; }
            // count lines with = ?
            if t.contains('=') { dep_count += 1; }
        }
    }
    Some((desc, ver, dep_count))
}

fn parse_package_json(repo: &Path) -> Option<(Option<String>, usize)> {
    let p = repo.join("package.json");
    let content = std::fs::read_to_string(&p).ok()?;
    // naive: find "version": "..." and count dependencies?
    // Use serde_json if available? Use simple parsing via serde_json
    let v: serde_json::Value = serde_json::from_str(&content).ok()?;
    let ver = v.get("version").and_then(|x| x.as_str()).map(|s| s.to_string());
    let deps = v.get("dependencies").and_then(|x| x.as_object()).map(|o| o.len()).unwrap_or(0);
    Some((ver, deps))
}

