    // naive: find "version": "..." and count dependencies?
    // Use serde_json if available? Use simple parsing via serde_json
    let v: serde_json::Value = serde_json::from_str(&content).ok()?;
    let ver = v.get("version").and_then(|x| x.as_str()).map(|s| s.to_string());
    let deps = v.get("dependencies").and_then(|x| x.as_object()).map(|o| o.len()).unwrap_or(0);
