fn is_excluded(path: &str, patterns: &[String]) -> bool {
    if patterns.is_empty() { return false; }
    for pat in patterns {
        // Use glob matching: try globset or simple fnmatch?
        // Use glob crate? For simplicity, use regex conversion: * -> .*, ? -> ., etc.
        // Also handle directory? If pat matches any part?
        // Original uses globset with patterns matched against relative paths? Let's implement simple:
