        // For now, implement simple: if pat == path, or pat == "*" etc.
        // Use `globset`? Not in deps. Use simple wildcard match.
        if simple_glob_match(pat, path) { return true; }
        // Also check basename? e.g., "*.rs" should match "src/main.rs"? Our simple match should handle `*` matching `/`? In glob, `*` does not match `/` by default? But original `*.rs` matched `app.rs` in root, but would it match `src/app.rs`? Likely yes (since **?). For simplicity, match basename as well?
        if let Some(base) = Path::new(path).file_name().and_then(|s| s.to_str()) {
