fn simple_glob_match(pat: &str, s: &str) -> bool {
    // convert glob to regex: * -> .*, ? -> ., [..] keep?
    let mut re = String::from("^");
    let mut chars = pat.chars().peekable();
    while let Some(c) = chars.next() {
        match c {
            '*' => {
                if chars.peek() == Some(&'*') {
                    chars.next();
                    // ** -> .*
                    re.push_str(".*");
                    // skip following / ?
                    if chars.peek() == Some(&'/') { chars.next(); re.push_str("(.*/)?"); }
                } else {
                    re.push_str("[^/]*");
                }
            },
            '?' => re.push_str("[^/]"),
            '[' => {
                re.push('[');
                // copy until ]
                while let Some(cc) = chars.next() {
                    re.push(cc);
                    if cc == ']' { break; }
                }
            },
            '.' | '+' | '(' | ')' | '|' | '^' | '$' | '{' | '}' | '\\' => {
                re.push('\\'); re.push(c);
            },
            _ => re.push(c),
        }
    }
    re.push('$');
    regex::Regex::new(&re).map(|r| r.is_match(s)).unwrap_or(false)
}

