fn get_languages(repo: &Path, include_hidden: bool, exclude: &[String], type_filter: &[String]) -> Vec<(String, String, usize)> {
    // returns Vec<(display, enum, loc)>
    // Use git ls-files --cached --others --exclude-standard -z
    let out = ProcCommand::new("git").arg("-C").arg(repo).args(&["ls-files", "--cached", "--others", "--exclude-standard", "-z"]).output();
    let mut files: Vec<String> = vec![];
    if let Ok(o) = out {
        if o.status.success() {
            let bytes = &o.stdout;
            let mut start = 0;
            for i in 0..bytes.len() {
                if bytes[i]==0 {
                    let s = String::from_utf8_lossy(&bytes[start..i]).to_string();
                    if !s.is_empty() { files.push(s); }
                    start = i+1;
                }
            }
        }
    }
    let mut map: HashMap<String, (String, String, usize)> = HashMap::new(); // enum -> (display, type, loc)
    for f in files {
        // hidden check
        if !include_hidden {
            // check if any component starts with .
            let mut hidden = false;
            for comp in Path::new(&f).components() {
                if let Some(s) = comp.as_os_str().to_str() {
                    if s.starts_with('.') && s != "." && s != ".." { hidden = true; break; }
                }
            }
            if hidden { continue; }
        }
        if is_excluded(&f, exclude) { continue; }
        if let Some((display, enum_name, typ)) = lang_for_file(&f) {
            if !type_filter.contains(&typ.to_string()) { continue; }
            // count LOC for this file
            let full = repo.join(&f);
            let loc = count_loc(&full, enum_name);
            if loc == 0 { continue; }
            let e = map.entry(enum_name.to_string()).or_insert((display.to_string(), typ.to_string(), 0));
            e.2 += loc;
        }
    }
    let mut v: Vec<(String, String, usize)> = map.into_iter().map(|(enum_n,(disp,_typ,loc))| (disp, enum_n, loc)).collect();
    // sort by loc desc, then display asc for determinism
    v.sort_by(|a,b| b.2.cmp(&a.2).then(a.0.cmp(&b.0)));
    v
}

fn count_loc(path: &Path, lang_enum: &str) -> usize {
    let content = match std::fs::read_to_string(path) {
        Ok(c) => c,
        Err(_) => return 0,
    };
    // determine comment prefix
    let single: Option<&str> = match lang_enum {
        "Python" => Some("#"),
        "Rust" | "Go" | "Java" | "C" | "Cpp" | "JavaScript" | "TypeScript" | "Jsx" | "Tsx" | "Kotlin" | "Scala" | "Swift" | "CSharp" | "Dart" | "D" => Some("//"),
        "Sh" | "Bash" | "Zsh" | "Fish" | "Shell" => Some("#"),
        "Ruby" | "Perl" | "R" | "Lua" => Some("#"),
        "Haskell" | "Elm" => Some("--"),
        "Html" | "Xml" => None, // handle <!-- -->? For simplicity, count non-blank
        _ => Some("#"),
    };
    let mut cnt=0;
    let mut in_block = false;
    for line in content.lines() {
        let t = line.trim();
        if t.is_empty() { continue; }
        if in_block {
            if t.contains("*/") { in_block = false; }
            continue;
        }
        if t.starts_with("/*") {
            if !t.contains("*/") { in_block = true; }
            continue;
        }
        if let Some(p) = single {
            if t.starts_with(p) { continue; }
            // for Python, also handle """ docstrings? Ignore for simplicity
        }
        // for HTML/XML, handle <!-- ?
        if t.starts_with("<!--") { continue; }
        cnt+=1;
    }
    cnt
}

