    let no_palette = m.get_flag("no-color-palette");
    let no_art = m.get_flag("no-art");
    let nerd = m.get_flag("nerd-fonts");
    let output = m.get_one::<String>("output").cloned();

    // Re-get text-colors as u8
    let text_colors_u8: Vec<u8> = m.get_many::<u8>("text-colors").map(|v| v.cloned().collect()).unwrap_or(vec![]);
    let ascii_colors_u8: Vec<u8> = m.get_many::<u8>("ascii-colors").map(|v| v.cloned().collect()).unwrap_or(vec![]);

    // Gather repo data
    let username = get_username(&repo);
    let gver = git_version();
    let repo_name = get_repo_name(&repo);
    let n_branches = get_branches(&repo);
    let tags = get_tag_list(&repo);
    let n_tags = tags.len();
    let desc = get_description(&repo);
    // head
    let head_res = get_head(&repo);
    let (short_id, head_refs) = match head_res {
        Ok(v) => v,
        Err(e) => {
            eprintln!("Error: Failed to traverse Git commit history\n\nCaused by:\n    {}", e);
