    let version = get_version(&repo, &tags);
    let created_unix = get_created_unix(&repo, no_bots.is_some(), no_bots.as_deref(), no_merges).unwrap_or(0);
    let last_unix = get_last_change_unix(&repo).unwrap_or(0);
    let created_str = if iso_time { iso_time(created_unix) } else { humanize(created_unix) };
    let last_str = if iso_time { iso_time(last_unix) } else { humanize(last_unix) };
