    let (churn_all, pool) = get_churn(&repo, pool_opt, num_churns as u32, no_bots.clone(), no_merges, &exclude);
    let (size_str, file_count) = get_size(&repo);
    let license = get_license(&repo);
    let url = get_url(&repo, http_url, hide_token);

    // Build JSON if needed
    if let Some(fmt) = output {
        // Build infoFields respecting disabled
        // For JSON, number-of-authors truncates? Yes, authors truncated to num_authors? Earlier test showed authors truncated to 1 with --number-of-authors 1. Good.
