    r2=subprocess.run(["/tmp/dev/target/debug/dev"]+args+["--output","json"], capture_output=True, text=True, cwd=cwd)
    if r1.returncode!=r2.returncode:
        print(f"{args} rc mismatch {r1.returncode} vs {r2.returncode}")
        return
    j1=json.loads(r1.stdout)
    j2=json.loads(r2.stdout)
