    def norm(j):
        for f in j["infoFields"]:
            if "LanguagesInfo" in f:
                f["LanguagesInfo"]["languagesWithPercentage"] = sorted(f["LanguagesInfo"]["languagesWithPercentage"], key=lambda x: x["language"])
